func buildFBCommonGovernment(b *flatbuffers.Builder, v *ds.CommonGovernment) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBCommonGovernmentRow(b, &v.Rows[i])
		}
		fb.CommonGovernmentStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.CommonGovernmentStart(b)
	if oRows != 0 {
		fb.CommonGovernmentAddRows(b, oRows)
	}
	return fb.CommonGovernmentEnd(b)
}

func readFBCommonGovernment(t *fb.CommonGovernment, v *ds.CommonGovernment) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.CommonGovernmentRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBCommonGovernmentRow(&c, &v.Rows[i])
		}
	}
}

