func buildFBMotos(b *flatbuffers.Builder, v *ds.Motos) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBMotosRow(b, &v.Rows[i])
		}
		fb.MotosStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.MotosStart(b)
	if oRows != 0 {
		fb.MotosAddRows(b, oRows)
	}
	return fb.MotosEnd(b)
}

func readFBMotos(t *fb.Motos, v *ds.Motos) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.MotosRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBMotosRow(&c, &v.Rows[i])
		}
	}
}

