func buildFBNYC(b *flatbuffers.Builder, v *ds.NYC) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBNYCRow(b, &v.Rows[i])
		}
		fb.NYCStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.NYCStart(b)
	if oRows != 0 {
		fb.NYCAddRows(b, oRows)
	}
	return fb.NYCEnd(b)
}

func readFBNYC(t *fb.NYC, v *ds.NYC) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.NYCRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBNYCRow(&c, &v.Rows[i])
		}
	}
}

