func buildFBPhysicians(b *flatbuffers.Builder, v *ds.Physicians) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBPhysiciansRow(b, &v.Rows[i])
		}
		fb.PhysiciansStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.PhysiciansStart(b)
	if oRows != 0 {
		fb.PhysiciansAddRows(b, oRows)
	}
	return fb.PhysiciansEnd(b)
}

