func buildFBRentabilidad(b *flatbuffers.Builder, v *ds.Rentabilidad) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBRentabilidadRow(b, &v.Rows[i])
		}
		fb.RentabilidadStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.RentabilidadStart(b)
	if oRows != 0 {
		fb.RentabilidadAddRows(b, oRows)
	}
	return fb.RentabilidadEnd(b)
}

func readFBRentabilidad(t *fb.Rentabilidad, v *ds.Rentabilidad) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.RentabilidadRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBRentabilidadRow(&c, &v.Rows[i])
		}
	}
}

