func buildFBTelco(b *flatbuffers.Builder, v *ds.Telco) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBTelcoRow(b, &v.Rows[i])
		}
		fb.TelcoStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.TelcoStart(b)
	if oRows != 0 {
		fb.TelcoAddRows(b, oRows)
	}
	return fb.TelcoEnd(b)
}

func readFBTelco(t *fb.Telco, v *ds.Telco) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.TelcoRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBTelcoRow(&c, &v.Rows[i])
		}
	}
}

