func buildFBUSCensus(b *flatbuffers.Builder, v *ds.USCensus) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBUSCensusRow(b, &v.Rows[i])
		}
		fb.USCensusStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.USCensusStart(b)
	if oRows != 0 {
		fb.USCensusAddRows(b, oRows)
	}
	return fb.USCensusEnd(b)
}

func readFBUSCensus(t *fb.USCensus, v *ds.USCensus) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.USCensusRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBUSCensusRow(&c, &v.Rows[i])
		}
	}
}

