func buildFBUberlandia(b *flatbuffers.Builder, v *ds.Uberlandia) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBUberlandiaRow(b, &v.Rows[i])
		}
		fb.UberlandiaStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.UberlandiaStart(b)
	if oRows != 0 {
		fb.UberlandiaAddRows(b, oRows)
	}
	return fb.UberlandiaEnd(b)
}

func readFBUberlandia(t *fb.Uberlandia, v *ds.Uberlandia) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.UberlandiaRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBUberlandiaRow(&c, &v.Rows[i])
		}
	}
}

