func buildFBYaleLanguages(b *flatbuffers.Builder, v *ds.YaleLanguages) flatbuffers.UOffsetT {
	var oRows flatbuffers.UOffsetT
	if n := len(v.Rows); n > 0 {
		offsets := make([]flatbuffers.UOffsetT, n)
		for i := range v.Rows {
			offsets[i] = buildFBYaleLanguagesRow(b, &v.Rows[i])
		}
		fb.YaleLanguagesStartRowsVector(b, n)
		for i := n - 1; i >= 0; i-- {
			b.PrependUOffsetT(offsets[i])
		}
		oRows = b.EndVector(n)
	}
	fb.YaleLanguagesStart(b)
	if oRows != 0 {
		fb.YaleLanguagesAddRows(b, oRows)
	}
	return fb.YaleLanguagesEnd(b)
}

func readFBYaleLanguages(t *fb.YaleLanguages, v *ds.YaleLanguages) {
	v.Rows = formats.Resize(v.Rows, t.RowsLength())
	{
		var c fb.YaleLanguagesRow
		for i := range v.Rows {
			t.Rows(&c, i)
			readFBYaleLanguagesRow(&c, &v.Rows[i])
		}
	}
}

